class Order {
  constructor({ id, product, amount, status }) {
    this.id = id;
    this.product = product;
    this.amount = amount;
    this.status = status || 'pending';
    this.createdAt = new Date();
  }
}

module.exports = Order;

const orders = new Map();

class OrderRepository {
  save(order) {
    orders.set(order.id, order);
    return order;
  }

  findById(id) {
    return orders.get(id);
  }

  findAll() {
    return Array.from(orders.values());
  }

  clear() {
    orders.clear();
  }
}

module.exports = new OrderRepository();

const Order = require('../models/Order');
const orderRepository = require('../repository/OrderRepository');

class OrderService {
  create(orderData) {
    const order = new Order(orderData);
    return orderRepository.save(order);
  }
}

module.exports = new OrderService();

const orderService = require('../services/OrderService');

class OrderController {
  create(req, res) {
    try {
      const order = orderService.create(req.body);
      res.status(201).json(order);
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  }
}

module.exports = new OrderController();

const express = require('express');
const orderController = require('./controllers/OrderController');

const app = express();
app.use(express.json());

app.post('/api/orders', (req, res) => orderController.create(req, res));

module.exports = app;

const orderService = require('../src/services/OrderService');
const orderRepository = require('../src/repository/OrderRepository');

describe('OrderService.create', () => {
  beforeEach(() => {
    orderRepository.clear();
  });

  test('should create an order with valid data', () => {
    const order = orderService.create({
      id: 'order-001',
      product: 'Test Product',
      amount: 100.00,
    });

    expect(order).toBeDefined();
    expect(order.id).toBe('order-001');
    expect(order.amount).toBe(100.00);
    expect(order.status).toBe('pending');

    const saved = orderRepository.findById('order-001');
    expect(saved).toBeDefined();
    expect(saved.amount).toBe(100.00);
  });

  test('should reject order creation when amount is null', () => {
    expect(() => {
      orderService.create({
        id: 'order-002',
        product: 'Null Amount Product',
        amount: null,
      });
    }).toThrow('orders.amount');
  });

  test('should reject order creation when amount is undefined', () => {
    expect(() => {
      orderService.create({
        id: 'order-003',
        product: 'Undefined Amount Product',
        amount: undefined,
      });
    }).toThrow('orders.amount');
  });

  test('should reject order creation when amount is not a number', () => {
    expect(() => {
      orderService.create({
        id: 'order-004',
        product: 'String Amount Product',
        amount: 'not-a-number',
      });
    }).toThrow('orders.amount');
  });

  test('should reject order creation when amount is negative', () => {
    expect(() => {
      orderService.create({
        id: 'order-005',
        product: 'Negative Amount Product',
        amount: -50,
      });
    }).toThrow('orders.amount');
  });

  test('should reject order creation when amount is zero', () => {
    expect(() => {
      orderService.create({
        id: 'order-006',
        product: 'Zero Amount Product',
        amount: 0,
      });
    }).toThrow('orders.amount');
  });

  test('should not persist invalid orders to repository', () => {
    expect(() => {
      orderService.create({
        id: 'order-007',
        product: 'Bad Order',
        amount: null,
      });
    }).toThrow();

    const saved = orderRepository.findById('order-007');
    expect(saved).toBeUndefined();
  });
});

