function validate(validate, errors) { if (!validate) { console.error('Validation errors:'); console.error(errors); process.exit(1); } }
const schema = require('/work/input/result.schema.json');
const result = require('/work/output/result.json');

const errs = [];
const allowed = Object.keys(schema.properties);
for (const key of Object.keys(result)) {
  if (!allowed.includes(key)) { errs.push('Unexpected field: ' + key); }
}
for (const req of schema.required) {
  if (!(req in result)) { errs.push('Missing required field: ' + req); }
}
const enumProps = {};
for (const [k, v] of Object.entries(schema.properties)) {
  if (v.enum) { enumProps[k] = v.enum; }
  if (v.pattern && typeof result[k] === 'string' && !new RegExp(v.pattern).test(result[k])) {
    errs.push('Field ' + k + ' does not match pattern: ' + v.pattern);
  }
}
for (const [k, allowed] of Object.entries(enumProps)) {
  if (!allowed.includes(result[k])) { errs.push(k + ' must be one of: ' + allowed.join(', ') + ' but got: ' + result[k]); }
}
if (schema.properties.changedFiles && result.changedFiles && schema.properties.changedFiles.items && schema.properties.changedFiles.items.pattern) {
  for (const f of result.changedFiles) {
    if (!new RegExp(schema.properties.changedFiles.items.pattern).test(f)) {
      errs.push('Invalid file path: ' + f);
    }
  }
}
if (result.status !== 'NEED_INFO' && result.status !== 'FAILED' && result.changedFiles.length < 1) {
  errs.push('changedFiles must have at least 1 item for status ' + result.status);
}
if (result.status === 'SUCCESS' && (!result.prBody || result.prBody.length === 0)) {
  errs.push('prBody is required for SUCCESS status');
}
if (result.testStatus !== 'SKIPPED' && (!result.testCommands || result.testCommands.length < 1)) {
