console.log('status:', result.status);
console.log('changedFiles:', JSON.stringify(result.changedFiles));
console.log('testCommands:', JSON.stringify(result.testCommands));
console.log('testStatus:', result.testStatus);
console.log('riskLevel:', result.riskLevel);
